  B.BANK_RESULT = 2524660062                         -- the bank's pick (retail temp int)
  B.TEXT_GET = 4074371074                            -- CMND_TEXT_GET (text id)
  B.REFUSED = {none = 1158902640, known = 555889516}
  B.REFUSAL = 3947752921
