  B.REASON = {no_learned_move = -5, only_grey = -6, in_use = -7, no_move_for_base = -8, himself = -9, other = -10}
  B.BANK = 1981996040                                -- chara_bank_menu_for_search
  B.PLATE = 1427722143                               -- personal_plate_menu
